// Formal top for the qs-ques AXI master (tutorials/sv_testbench/axi_slave_testbench), stimulus from the
// UVM testbench's own constraints: fv_r_mem_req_item is generated by fvgen from mem_req_item.
//
// The glue below is mem_driver's req_loop written as RTL (one request outstanding): randomize an item,
// drive cpu_mem_* until cpu_mem_ready, derive byte_en as post_randomize() does. The AXI slave side is
// left free (every AXI input is unconstrained), so covers show what the DUT can do for legal requests.
module axi_fv_top (
  input logic clk,
  input logic reset
);
  `include "prim_assert.sv"

  // reset for the first cycle, as in the qs-ques formal examples
  logic rst_for_cycle = 1'b0;
  always_ff @(posedge clk) rst_for_cycle <= 1'b1;
  `ASSUME(first_cycle_reset, rst_for_cycle ^ reset, clk, 1'b0)

  // ---------------------------------------------------------------- constrained-random item
  logic        req_randomize;
  logic [31:0] addr, first_byte, num_bytes;
  logic [0:0]  wr;
  logic [1:0]  shape;
  logic [127:0] wr_data;
  fv_r_mem_req_item u_item (
    .clk, .reset, .randomize(req_randomize),
    .addr, .wr, .shape, .first_byte, .num_bytes, .wr_data
  );

  // ---------------------------------------------------------------- mem_driver as RTL
  logic        valid;
  logic        ready;
  logic [15:0] byte_en;
  assign req_randomize = !reset && !valid;              // next item as soon as the bus is free
  // post_randomize(): byte_en[first_byte +: num_bytes] = '1
  assign byte_en = 16'((17'h1 << num_bytes) - 17'h1) << first_byte[3:0];
  always_ff @(posedge clk) begin
    if (reset) valid <= 1'b0;
    else if (!valid) valid <= 1'b1;                     // item randomized this cycle, driven next
    else if (ready) valid <= 1'b0;
  end

  // ---------------------------------------------------------------- DUT, AXI side
  // FV_AXI_DRIVER: the UVM testbench's axi_slave_driver as RTL (axi_slave_driver_fv.sv); otherwise every
  // AXI input is free
  (* anyseq *) logic rsp_ready;
`ifdef FV_AXI_DRIVER
  logic aw_ready, w_ready, b_valid, ar_ready, r_valid, r_last;
  logic [2:0] b_id, r_id;
  logic [31:0] r_data;
`else
  (* anyseq *) logic aw_ready, w_ready, b_valid, ar_ready, r_valid, r_last;
  (* anyseq *) logic [2:0] b_id, r_id;
  (* anyseq *) logic [31:0] r_data;
`endif
  logic        aw_valid, w_valid, w_last, b_ready, ar_valid, r_ready, rsp_valid;
  logic [2:0]  aw_id, ar_id;
  logic [31:0] aw_addr, ar_addr, w_data;
  logic [1:0]  aw_len, ar_len;
  logic [2:0]  aw_size, ar_size;
  logic [3:0]  w_strb, rsp_id;
  logic [127:0] rsp_data;
`ifdef FV_AXI_DRIVER
  logic drv_q_overflow;
  axi_slave_driver_fv #(.QDEPTH(8)) u_axi_drv (
    .clk, .reset_n(!reset),
    .arvalid(ar_valid), .arid(ar_id), .arlen(ar_len), .awvalid(aw_valid), .awid(aw_id),
    .wvalid(w_valid), .wlast(w_last), .rready(r_ready), .bready(b_ready),
    .arready(ar_ready), .awready(aw_ready), .wready(w_ready), .rvalid(r_valid), .rid(r_id), .rdata(r_data),
    .rlast(r_last), .bvalid(b_valid), .bid(b_id), .q_overflow(drv_q_overflow));
  `ASSERT(drv_queue_fits, !drv_q_overflow)           // the model's request queues are deep enough
`endif

  axi_master DUT (
    .clk, .reset_n(!reset),
    .cpu_mem_valid_i(valid), .cpu_mem_id_i(4'd0), .cpu_mem_addr_i(addr), .cpu_mem_byte_en_i(byte_en),
    .cpu_mem_wr_i(wr), .cpu_mem_wr_data_i(wr_data), .cpu_mem_ready_o(ready),
    .mem_cpu_valid_o(rsp_valid), .mem_cpu_id_o(rsp_id), .mem_cpu_rd_data_o(rsp_data), .mem_cpu_ready_i(rsp_ready),
    .axi_awvalid_o(aw_valid), .axi_awid_o(aw_id), .axi_awaddr_o(aw_addr), .axi_awlen_o(aw_len),
    .axi_awsize_o(aw_size), .axi_awready_i(aw_ready),
    .axi_wvalid_o(w_valid), .axi_wdata_o(w_data), .axi_wstrb_o(w_strb), .axi_wlast_o(w_last), .axi_wready_i(w_ready),
    .axi_bvalid_i(b_valid), .axi_bid_i(b_id), .axi_bready_o(b_ready),
    .axi_arvalid_o(ar_valid), .axi_arid_o(ar_id), .axi_araddr_o(ar_addr), .axi_arlen_o(ar_len),
    .axi_arsize_o(ar_size), .axi_arready_i(ar_ready),
    .axi_rvalid_i(r_valid), .axi_rid_i(r_id), .axi_rdata_i(r_data), .axi_rlast_i(r_last), .axi_rready_o(r_ready)
  );

  // ---------------------------------------------------------------- checks / covers
  wire accepted = valid && ready;
  // every request the constraints allow is a contiguous run inside one 16-byte line
  `ASSERT(req_in_line, `IMPLIES(valid, first_byte + num_bytes <= 32'd16 && num_bytes != 0 && addr[3:0] == 4'h0))
  `ASSERT(req_byte_en_nonzero, `IMPLIES(valid, byte_en != 16'h0))
  `COVER(full_line_write, accepted && wr && shape == 2'd0)
  `COVER(full_lanes_write, accepted && wr && shape == 2'd1 && byte_en != 16'hffff)
  `COVER(single_byte_read, accepted && !wr && num_bytes == 32'd1)
  `COVER(axi_partial_strobe, w_valid && w_ready && w_strb != 4'hf && w_strb != 4'h0)
  `COVER(axi_write_last, w_valid && w_ready && w_last)
  `COVER(axi_read_issued, ar_valid && ar_ready)
  // the AXI responses come back to the DUT and on to the CPU side
  logic ar_seen = 1'b0, aw_seen = 1'b0;
  always_ff @(posedge clk) begin
    if (ar_valid && ar_ready) ar_seen <= 1'b1;
    if (aw_valid && aw_ready) aw_seen <= 1'b1;
  end
  `COVER(axi_read_data_beat, r_valid && r_ready)
  `COVER(axi_write_response, b_valid && b_ready)
  `COVER(cpu_read_response, rsp_valid && rsp_ready)
  // behaviours the UVM testbench never produces: a read beat with no AR issued, a write response with no
  // write issued. Reachable with free AXI inputs; with FV_AXI_DRIVER they must be unreachable
  `COVER(spurious_r_beat, r_valid && r_ready && !ar_seen)
  `COVER(spurious_b_resp, b_valid && b_ready && !aw_seen)
endmodule
